assert(null, "default");
assert("", "default");
assert("a");
assert("b", "default");
assert("ab");
assert("abc");
assert("abcd");
assert("abcde");
assert("abcdef");
assert("not", "default");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(object o)
    {
        return o switch
        {
            "a" => "a",
            "ab" => "ab",
            "abc" => "abc",
            "abcd" => "abcd",
            "abcde" => "abcde",
            "abcdef" => "abcdef",
            "abcdefg" => "abcdefg",
            "abcdefgh" => "abcdefgh",
            _ => "default"
        };
    }
}
